// check-revision-scope.mjs — is a successor commit an honest, bounded revision of its predecessor?
//
// Checks only the *mechanics* of a revision (what changed, where, and whether claimed-unchanged
// paths are byte-identical). It does not judge whether the change is correct.
//
// Usage:
//   node check-revision-scope.mjs --repo <path> --predecessor <rev> --successor <rev>
//        [--allow <glob>]...        paths the revision may change (at least one required)
//        [--require <path>]...      paths that must appear among the changes
//        [--unchanged <path>]...    paths (files or directories) that must be identical
//        [--expect-commit <sha>]    the successor must resolve to exactly this full commit id
//
// Prints one JSON object. Exit 0 = PASS, 1 = HOLD, 2 = usage or git error.
import { spawnSync } from 'node:child_process';

function parse(argv) {
  const o = { allow: [], require: [], unchanged: [] };
  for (let i = 0; i < argv.length; i += 2) {
    const k = argv[i]?.replace(/^--/, '');
    const v = argv[i + 1];
    if (!argv[i]?.startsWith('--') || v === undefined) throw new Error(`bad argument near "${argv[i]}"`);
    if (['allow', 'require', 'unchanged'].includes(k)) o[k].push(v);
    else if (['repo', 'predecessor', 'successor', 'expect-commit'].includes(k)) o[k] = v;
    else throw new Error(`unknown option --${k}`);
  }
  for (const k of ['repo', 'predecessor', 'successor'])
    if (!o[k]) throw new Error(`--${k} is required`);
  if (o.allow.length === 0) throw new Error('at least one --allow is required (a revision with no authorised surface is HOLD by definition)');
  return o;
}

function git(repo, args) {
  const r = spawnSync('git', ['-C', repo, ...args], { encoding: 'utf8' });
  if (r.error) throw r.error;
  return { status: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
}

const norm = (p) => p.replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/+$/, '');
