// run-harness.mjs — one frozen, repeatable way to run the shipped harness on Windows.
//
// Why it exists: a handoff's frozen run_command is an exact string in a seat's allowlist,
// but the harness refuses an output directory that already exists, so a bare command can run
// only once. This wrapper keeps the command string fixed and picks a fresh output directory
// itself on every run. It also applies the documented Windows invocation (the path-separator
// patch and UTF-8 mode) so the Microsoft Store `python` shim is never used.
//
// Usage:
//   node run-harness.mjs --harness-dir <dir> --python <exe> --track <track> --stage <n>
//        --checks-root <dir> [--repo <dir>] [--label <name>] [--mode isolated|host] [--dry-run]
//
// --repo defaults to the current working directory and --label to its folder name, so the same
// frozen command works for any seat's own working copy. All paths must be absolute.
// Prints the output directory as `OUT=<path>`; exits with the harness's exit code
// (2 for usage errors, 3 if no unique output directory could be allocated).
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync } from 'node:fs';
import { basename, isAbsolute, join, resolve } from 'node:path';

const PATCH =
  "import pathlib,sys; original=pathlib.WindowsPath.__str__; " +
  "pathlib.WindowsPath.__str__=lambda p:original(p).replace(chr(92),'/'); " +
  "from harness.cli import main; sys.exit(main())";

function parse(argv) {
  const o = { mode: 'isolated', dry: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--dry-run') { o.dry = true; continue; }
    if (!a.startsWith('--') || argv[i + 1] === undefined) throw new Error(`bad argument near "${a}"`);
    const k = a.slice(2);
    if (!['harness-dir', 'python', 'track', 'stage', 'checks-root', 'repo', 'label', 'mode'].includes(k))
      throw new Error(`unknown option --${k}`);
    o[k] = argv[++i];
  }
  for (const k of ['harness-dir', 'python', 'track', 'stage', 'checks-root'])
    if (!o[k]) throw new Error(`--${k} is required`);
  if (!['isolated', 'host'].includes(o.mode)) throw new Error('--mode must be isolated or host');
  if (!/^\d+$/.test(o.stage)) throw new Error('--stage must be a whole number');
  if (!/^[a-z0-9_-]+$/i.test(o.track)) throw new Error('--track has an invalid character');
