  o.label = (o.label ?? basename(o.repo)).replace(/[^A-Za-z0-9_-]/g, '-');
  for (const k of ['harness-dir', 'python', 'checks-root', 'repo'])
    if (!isAbsolute(k === 'repo' ? o.repo : o[k])) throw new Error(`--${k} must be an absolute path`);
