//
//   node factory/scripts/seal-packet.mjs seal   < fields.json   -> sealed packet JSON on stdout
//   node factory/scripts/seal-packet.mjs verify < packet.json   -> {ok, errors}
//   node factory/scripts/seal-packet.mjs sha256 < any-text      -> hex digest of the exact bytes
//
// Reads stdin only, writes stdout only, touches no file or network. `seal` refuses to emit a packet
// that fails validatePacket (exit 1). Exit 2 = usage or unreadable input.
import { sealPacket, validatePacket } from '../contracts/handoff_contract.mjs';
import { createHash } from 'node:crypto';

const chunks = [];
for await (const c of process.stdin) chunks.push(c);
const raw = Buffer.concat(chunks);
const mode = process.argv[2];

const parse = () => {
  try { return JSON.parse(raw.toString('utf8')); }
  catch (e) { console.error(`stdin is not JSON: ${e.message}`); process.exit(2); }
};

if (mode === 'sha256') {
  console.log(createHash('sha256').update(raw).digest('hex'));
} else if (mode === 'seal') {
  const { packet_hash, schema_version, ...fields } = parse();
  const sealed = sealPacket(fields);
  const v = validatePacket(sealed);
  if (!v.ok) { console.error(JSON.stringify(v)); process.exit(1); }
  console.log(JSON.stringify(sealed, null, 2));
} else if (mode === 'verify') {
  const v = validatePacket(parse());
  console.log(JSON.stringify(v));
  process.exit(v.ok ? 0 : 1);
} else {
  console.error('usage: seal-packet.mjs seal|verify|sha256 < stdin');
  process.exit(2);
}
